/* Shared presentation components. No policy writes or invented progress. */
(() => {
  'use strict';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const text=(s,az,en)=>s.lang==='az'?az:en;
  const paths={
    grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',
    library:'<path d="M4 4h6v16H4zM10 4h6v16h-6zM18 4l3 15-3 1-3-15z"/>',
    publish:'<path d="M12 16V3m-5 5 5-5 5 5M4 14v6h16v-6"/>',
    network:'<rect x="8" y="2" width="8" height="5" rx="1"/><path d="M12 7v6M5 17v-4h14v4"/><rect x="2" y="17" width="6" height="5" rx="1"/><rect x="16" y="17" width="6" height="5" rx="1"/>',
    shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6zM8 12l3 3 5-6"/>',
    alert:'<path d="m12 3 10 18H2zM12 9v5m0 3v1"/>',activity:'<path d="M2 12h4l3-8 6 16 3-8h4"/>',
    settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',
    search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M19 12a7 7 0 0 0-12-5L4 10m16 4-3 3a7 7 0 0 1-12-5"/>',
    sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',
    moon:'<path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11z"/>',
    help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4m0 3v1"/>',
    menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',panel:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M9 3v18"/>',
    check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    undo:'<path d="M3 9h12a6 6 0 0 1 0 12M3 9l5-5M3 9l5 5"/>',file:'<path d="M4 3h11l5 5v13H4zM15 3v5h5M8 12h8M8 16h8"/>',
    key:'<circle cx="8" cy="9" r="5"/><path d="m12 13 8 8m-3-3 3-3m-6 0 3-3"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
    folder:'<path d="M3 6h7l2 3h9v12H3z"/>',wifi:'<path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-11 4a5 5 0 0 1 8 0m-4 4v1"/>',
    user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',close:'<path d="m5 5 14 14M5 19 19 5"/>',star:'<path d="m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',chevron:'<path d="m9 5 7 7-7 7"/>'
  };
  function icon(name){return `<svg class="ui-icon" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.shield}</svg>`;}
  const domains={1:'key',2:'shield',3:'file',4:'user',5:'settings',6:'grid',7:'folder',8:'network',9:'shield',10:'network',11:'wifi',12:'key',13:'lock',14:'shield',15:'grid',16:'lock',17:'activity',18:'settings',19:'user'};
  function status(s,value){
    const v=String(value||'UNKNOWN').toUpperCase();
    const known={PUBLISHED:['Yayımlanıb','Published'],NO_CHANGE:['Dəyişiklik yoxdur','No change'],ROLLED_BACK:['Geri qaytarılıb','Rolled back'],APPLYING:['Tətbiq edilir','Applying'],VERIFYING:['Yoxlanılır','Verifying'],FAILED_SAFE:['Təhlükəsiz dayandırılıb','Safely stopped'],DRIFT_DETECTED:['Kənar dəyişiklik aşkarlanıb','Drift detected'],VERIFY_MISMATCH:['Uyğunsuzluq','Mismatch'],REVIEW_REQUIRED:['Yoxlama tələb edir','Needs review'],VERIFIED_ON_SAMPLE:['Nümunədə təsdiqlənib','Verified on sample'],DOMAIN_VALUE_MATCHES_ON_SELECTED_DC:['Seçilmiş DC-də uyğundur','Matches on selected DC'],REPLICATION_PENDING:['Yayılma gözlənilir','Replication pending'],ENDPOINT_VERIFICATION_PENDING:['Son cihaz yoxlaması gözlənilir','Endpoint verification pending'],REFRESH_SCHEDULED:['Yenilənmə planlaşdırılıb','Refresh scheduled'],ROLLBACK_ENDPOINT_PENDING:['Bərpadan sonra yoxlama gözlənilir','Post-rollback verification pending'],PUBLISHED_REFRESH_FAILED:['Yayımlanıb, yenilənmə alınmayıb','Published, refresh failed']};
    const tone=v==='ROLLED_BACK'?'neutral':/FAIL|ERROR|DRIFT|MISMATCH|REVIEW|PARTIAL/.test(v)?'danger':/^(PUBLISHED|NO_CHANGE|VERIFIED_ON_SAMPLE|DOMAIN_VALUE_MATCHES_ON_SELECTED_DC)$/.test(v)?'success':'pending';
    const symbol=v==='ROLLED_BACK'?'undo':tone==='danger'?'alert':tone==='success'?'check':'clock';
    const label=known[v]?text(s,...known[v]):v.replaceAll('_',' ');
    return {tone,label,icon:symbol,html:`<span class="ds-badge ds-${tone}">${icon(symbol)}${esc(label)}</span>`};
  }
  function breadcrumb(s,rule){const sections=s.catalog.sections,domain=sections.find(x=>!x.parentId&&rule.id.startsWith(x.id+'.')),section=sections.find(x=>x.id===rule.sectionId);return `<nav class="ds-breadcrumb" aria-label="${text(s,'Səhifə yolu','Breadcrumb')}"><a href="#/benchmark">Benchmark</a>${domain?`<span aria-hidden="true">/</span><button data-breadcrumb-domain="${esc(domain.id)}">${esc(domain.title)}</button>`:''}${section&&section.id!==domain?.id?`<span aria-hidden="true">/</span><span>${esc(section.title)}</span>`:''}<span aria-hidden="true">/</span><strong aria-current="page">${esc(rule.id)}</strong></nav>`;}
  function operations(s,runs){return `<div class="ds-table-wrap"><table class="ds-table"><caption class="sr-only">${text(s,'Əməliyyatlar və qeyd edilmiş nəticələr','Operations and recorded outcomes')}</caption><thead><tr>${[text(s,'Qayda / GPO','Control / GPO'),text(s,'Vəziyyət','Status'),text(s,'İcra hesabı','Operator'),text(s,'Vaxt','Time'),text(s,'Detallar','Details')].map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${runs.map(h=>`<tr><td><strong>${esc(h.plan?.selection?.setting||'GPO')}</strong><small>${esc(h.plan?.preview?.gpo?.name||'—')}</small></td><td>${status(s,h.result?.state).html}</td><td>${esc(h.plan?.executionUser||'—')}</td><td><time datetime="${esc(h.updatedAt||'')}">${window.GpoProduct.date(h.updatedAt,s.lang)}</time></td><td><button class="ds-button ds-secondary ds-sm" data-inspect="${esc(h.id)}">${text(s,'Detalları aç','View details')}${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`;}
  function timeline(s,h){const r=h.result||{},steps=[[text(s,'Plan','Preview'),!!h.plan],[text(s,'Təsdiq','Approval'),!!h.approval],[text(s,'Ehtiyat nüsxə','Backup'),!!r.backupId],[text(s,'GPO dəyişikliyi','GPO write'),r.gpoPublished===true],[text(s,'Hədəf əlaqəsi','Target link'),r.linkVerified===true],[text(s,'Yayılma','Replication'),r.verification?.replicationConverged===true],[text(s,'Faktiki nəticə','Effective result'),window.GpoUiDomain.effectiveVerified(r.effectiveStatus)]];return `<ol class="ds-timeline" aria-label="${text(s,'Qeyd edilmiş mərhələlər','Recorded stages')}">${steps.map(([label,done],index)=>`<li class="${done?'done':''}">${icon(done?'check':'clock')}<strong>${label}</strong><span>${r.state==='NO_CHANGE'&&[2,3].includes(index)?text(s,'Tələb olunmur','Not required'):done?text(s,'Qeyddə təsdiqlənib','Confirmed in record'):text(s,'Təsdiqlənməyib','Not confirmed')}</span></li>`).join('')}</ol><p class="ds-caption">${text(s,'Mərhələlər serverin son qeydinə əsaslanır; bu, canlı faiz göstəricisi deyil.','Stages reflect the latest server record, not a live percentage.')}</p>`;}
  function domainEvidence(s){return `<section class="ds-evidence"><h2>${text(s,'Domenlər üzrə qeyd edilmiş nəticələr','Recorded outcomes by domain')}</h2><p>${text(s,'Son əməliyyatların xülasəsidir. GPO və hədəflər arasında ümumi uyğunluq balı hesablanmır.','Summary of latest operations. No compliance score is inferred across GPOs and targets.')}</p><div class="ds-evidence-grid">${s.catalog.sections.filter(d=>!d.parentId).map(d=>{const rules=s.catalog.rules.filter(r=>r.id.startsWith(d.id+'.')),results=rules.map(r=>window.GpoProduct.controlStatus(s,r)),verified=results.filter(r=>r.tone==='good').length,review=results.filter(r=>r.tone==='warning').length,recorded=results.filter(r=>r.run).length;return `<button data-dashboard-domain="${esc(d.id)}" class="${review?'review':verified?'verified':''}"><span>${esc(d.id)} · ${esc(d.title)}</span><strong>${verified} / ${rules.length}</strong><small>${recorded?`${recorded} ${text(s,'qeyd','recorded')} · ${review} ${text(s,'yoxlama','review')}`:text(s,'Yoxlanmayıb','Not assessed')}</small></button>`;}).join('')}</div></section>`;}
  function skeleton(s){return `<section class="ds-loading" role="status" aria-live="polite"><h1>${text(s,'İş sahəsi yüklənir','Loading workspace')}</h1><div class="ds-skeleton"></div><div class="ds-skeleton"></div><div class="ds-skeleton short"></div><p>${text(s,'Benchmark və xidmət məlumatları alınır.','Fetching benchmark and service information.')}</p></section>`;}
  function auditChain(s){const a=s.audit;if(!a)return '';const valid=a.integrityValid===true,broken=a.firstInvalidEventId;return `<section class="ds-chain ${valid?'valid':'broken'}" aria-label="${text(s,'Audit zənciri','Audit chain')}"><div>${icon(valid?'shield':'alert')}<strong>${valid?text(s,'Hash zənciri təsdiqlənib','Hash chain verified'):text(s,'Hash zəncirində uyğunsuzluq','Hash chain mismatch')}</strong></div><p>${broken?`${text(s,'İlk uyğunsuz hadisə','First invalid event')}: #${esc(broken)}`:valid?text(s,'Server bütün zəncirin hash və əlaqələrini yoxlayıb.','The server verified hashes and links across the entire chain.'):text(s,'Yoxlama tələb olunur.','Review required.')}</p><div class="ds-chain-nodes">${(a.events||[]).slice(0,10).map(e=>`<span class="${e.id===broken?'invalid':''}" title="${esc(e.hash)}">#${esc(e.id)}</span>`).join('<i aria-hidden="true"></i>')}</div></section>`;}
  function activity(s,runs){
    const items=window.GpoProduct.sortedRuns(runs).slice(0,8).map(h=>({h,start:Date.parse(h.startedAt||''),end:Date.parse(h.updatedAt||'')})).filter(x=>Number.isFinite(x.end));
    if(!items.length)return '';
    const min=Math.min(...items.map(x=>Number.isFinite(x.start)?Math.min(x.start,x.end):x.end)),max=Math.max(...items.map(x=>x.end)),range=Math.max(1,max-min);
    return `<details class="ds-activity"><summary>${icon('activity')}${text(s,'Əməliyyat zaman xətti','Operation timeline')}</summary><p class="ds-caption">${text(s,'Başlama və son yenilənmə vaxtları server qeydlərindən götürülür. Mərhələlərin müddəti ayrıca ölçülmür.','Start and last-update times come from server records. Individual stage durations are not measured.')}</p>${items.map(({h,start,end})=>{const known=Number.isFinite(start)&&start<=end;return `<button data-inspect="${esc(h.id)}" class="ds-activity-row"><span><strong>${esc(h.plan?.selection?.setting||'GPO')}</strong><small>${window.GpoProduct.date(h.updatedAt,s.lang)}</small></span><span class="ds-activity-track" aria-hidden="true"><i style="margin-left:${(known?start-min:end-min)/range*95}%;width:${known?Math.max(1,(end-start)/range*95):1}%"></i></span><span>${known?`${Math.round((end-start)/1000)} ${text(s,'san.','sec.')}`:text(s,'Başlama vaxtı yoxdur','Start unavailable')}</span></button>`;}).join('')}</details>`;
  }
  window.GpoComponents=Object.freeze({esc,text,icon,domainIcon:id=>icon(domains[id]||'shield'),status,breadcrumb,operations,timeline,domainEvidence,skeleton,auditChain,activity});
})();
